/* 0065_marketplace_facets.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
create or replace function public.marketplace_facets(p_topic text default null) returns table (kind text, value text, count bigint) language sql stable set search_path = public as $$ with topic as ( select nullif(nullif(btrim(coalesce(p_topic, '')), ''), 'general') as slug ), offered as ( select m.* from public.marketplace_listings m cross join topic t where m.status = 'active' and (t.slug is null or m.accepted_niches @> array[t.slug]) ) select 'niche'::text, m.niche, count(*) from public.marketplace_listings m where m.status = 'active' group by m.niche union all select 'language'::text, m.language, count(*) from public.marketplace_listings m where m.status = 'active' group by m.language union all select 'country'::text, o.country, count(*) from offered o where o.country is not null group by o.country union all select 'country-unstated'::text, ''::text, count(*) from offered o where o.country is null; $$;
comment on function public.marketplace_facets(text) is 'Niche, language and country counts for the marketplace sidebar. Niche and language over every active listing, country over the topic being bought for - which is what the page computed before filtering moved into the database.';
